  [26527] = { "$D1の間、術者の攻撃速度を$N1%、術者が与えるPhysicalダメージを$N2増加させます。", "与える物理ダメージが$N1増加しています。\n攻撃速度が$N2%上昇しています。", 0x1d3f8a49, 0xbc6c8e1d, "uu" },
