  [26532] = { "Right Clickでお手伝いさんを呼び出したり帰したりします。呼び出すにはSnowballが必要です。", nil, 0x8793840c, nil, "um" },
  [26533] = { "右クリックで Father Winter's Helperを召喚/退散します。", nil, 0xc04a0643, nil, "um" },
  [26534] = { "Right Clickでお手伝いを呼び出したり帰したりします。", nil, 0xc04a0643, nil, "um" },
