  [26540] = { "月光の雨を降らせ、$D2の間、選んだ範囲内のすべての敵を$D1ごとに焼き、$N1のArcaneダメージを与えます。", "$D1ごとに$N1のArcaneダメージを受けています。", 0xf1ec3c7a, 0xd8708d96, "uu" },
  [26541] = { "右クリックでWinter's Little Helperを召喚/退散します。召喚にはSnowballが必要です。", nil, 0x8793840c, nil, "um" },
  [26546] = { "25から45フィートの間にいる敵に影の矢を投げつけます。", nil, 0x4853b9d8, nil, "um" },
  [26548] = { "$D2の間、$D1ごとに敵にPhysicalダメージを与えます。", "$D1ごとに$N1のダメージを受けています。", 0x922b6035, 0x2613e2e6, "uu" },
  [26550] = { "$D1持続する雷雲を作り出し、選択した範囲のすべての敵に$N2のNatureダメージを与え、$D2ごとに$N3の追加ダメージを与えます。", nil, 0x9a2f7afe, nil, "um" },
  [26552] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
