  [26554] = { "近くのすべての敵に$N1の自然ダメージを与えます。", nil, 0x2162314b, nil, "um" },
  [26555] = { "25から45フィートの間にいる敵に影の矢を投げつけます。", nil, 0x4853b9d8, nil, "um" },
