  [26565] = { "対象を$N1回復します", nil, 0x919160a9, nil, "um" },
  [26573] = { "パラディンの足元の大地を清め、範囲に入った敵に$D1かけて$N1のHolyダメージを与えます。範囲に最初に入った$N3体の敵は、$D2かけてさらに$N4のダメージを受けます。", nil, 0x89dae0b8, nil, "um" },
  [26580] = { "敵を恐怖に陥れ、最大$D1の間、恐怖で逃げ回らせます。一度に恐怖状態にできる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x7ea26162, 0xfa67e4a8, "uu" },
  [26587] = { "Scarab Cofferを開けます。", nil, 0x7abe9266, nil, "um" },
  [26588] = { "Greater Scarab Cofferを開けます。", nil, 0xb1ca821b, nil, "um" },
  [26590] = { "$D2の間、$D1ごとに周囲の敵に$N1のNatureダメージを与えます。", "$D1ごとに$N1のNatureダメージを受けています。", 0xa5f95a74, 0xf6322bec, "uu" },
  [26601] = { "敵に毒を放ってNatureダメージを与え、さらに$D2の間、$D1ごとに追加のダメージを与えます。", "$D1ごとに$N1の自然ダメージを受けています。", 0x2c66ca3a, 0xaee3cc02, "uu" },
  [26607] = { "氷のかけらが対象範囲に降り注ぎ、$D1かけて$N1のFrostダメージを与えます。", "$N2秒ごとに$N1のFrostダメージを受けます。\n移動速度が$N3%低下します。", 0x9b941c1f, 0x6facc73b, "uu" },
